using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1StoryApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";
 static string Root=>Path.GetFullPath(Application.dataPath+"/../../..");static string Out=>Root+"/Docs/Review/2026-11-13_1F_EnvironmentalStory/";
 static Dictionary<string,Material> mats;static List<object> instances=new List<object>();
 static void Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F edit required");}
 static void PrepareMaterials(){string path=E+"Materials/AE_M_FallenConcrete.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/AE_M_Concrete.mat")){name="AE_M_FallenConcrete"};m.SetColor("_BaseColor",new Color(.51f,.49f,.43f));m.SetFloat("_Smoothness",.10f);AssetDatabase.CreateAsset(m,path);}mats=Directory.GetFiles(E+"Materials","AE_M_*.mat").Select(p=>AssetDatabase.LoadAssetAtPath<Material>(p.Replace('\\','/'))).Where(a=>a).ToDictionary(a=>a.name);}
 public static object RefineModels(){Check();PrepareMaterials();instances.Clear();var group=GameObject.Find("EnvironmentalStory").transform;foreach(var q in JArray.Parse(File.ReadAllText(Root+"/SourceAssets/F1_EnvironmentalStory/models.json")).Where(q=>(string)q["kind"]=="roofFall")){var proto=Import(q);var t=group.Find(proto.name);if(!t){Attach(proto,group);continue;}var source=proto.GetComponentsInChildren<MeshFilter>().ToDictionary(f=>f.name);foreach(var f in t.GetComponentsInChildren<MeshFilter>(true)){var src=source[f.name];f.sharedMesh=src.sharedMesh;f.GetComponent<Renderer>().sharedMaterials=src.GetComponent<Renderer>().sharedMaterials;PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f.GetComponent<Renderer>());}t.GetComponent<LODGroup>().RecalculateBounds();}var list=JArray.Parse(File.ReadAllText(Out+"apply.json"));foreach(var item in instances)list.Add(JObject.FromObject(item));File.WriteAllText(Out+"apply.json",list.ToString());AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return new{refined=true,added=instances.Count};}
 static GameObject Import(JToken q){string name=(string)q["name"],path=E+name+".fbx";string guid=AssetDatabase.AssetPathToGUID(path);File.Copy(Path.Combine(Path.GetTempPath(),"AfterSeconds_EnvironmentalStory_20261113/candidate/"+name+".fbx"),path,true);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var im=(ModelImporter)AssetImporter.GetAtPath(path);im.isReadable=false;im.importAnimation=false;im.importCameras=false;im.importLights=false;foreach(string n in q["materials"].Values<string>())im.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),n),mats[n]);im.SaveAndReimport();if(!string.IsNullOrEmpty(guid)&&guid!=AssetDatabase.AssetPathToGUID(path))throw new Exception("GUID changed "+name);return AssetDatabase.LoadAssetAtPath<GameObject>(path);}
 static void Attach(GameObject proto,Transform parent){if(parent.Find(proto.name))throw new Exception("Already attached "+proto.name);var go=(GameObject)PrefabUtility.InstantiatePrefab(proto,parent);go.name=proto.name;go.transform.localPosition=Vector3.zero;go.transform.localRotation=Quaternion.identity;go.transform.localScale=Vector3.one;foreach(var t in go.GetComponentsInChildren<Transform>())GameObjectUtility.SetStaticEditorFlags(t.gameObject,StaticEditorFlags.BatchingStatic);var rr=go.GetComponentsInChildren<Renderer>();var g=go.GetComponent<LODGroup>();if(!g)g=go.AddComponent<LODGroup>();g.SetLODs(new[]{new LOD(.16f,rr.Where(r=>r.name.EndsWith("LOD0")).ToArray()),new LOD(.06f,rr.Where(r=>r.name.EndsWith("LOD1")).ToArray()),new LOD(.012f,rr.Where(r=>r.name.EndsWith("LOD2")).ToArray())});g.RecalculateBounds();instances.Add(new{asset=AssetDatabase.GetAssetPath(proto),parent=AnimationUtility.CalculateTransformPath(parent,null),name=proto.name,dynamic=false});}
 public static object Run(){Check();mats=Directory.GetFiles(E+"Materials","AE_M_*.mat").Select(p=>AssetDatabase.LoadAssetAtPath<Material>(p.Replace('\\','/'))).Where(m=>m).ToDictionary(m=>m.name);var scene=SceneManager.GetActiveScene();var root=GameObject.Find("1F_AbandonedFactory").transform;if(root.position!=Vector3.zero||root.rotation!=Quaternion.identity||root.lossyScale!=Vector3.one)throw new Exception("Unexpected factory root");
 string backup=Path.Combine(Path.GetTempPath(),"AfterSeconds_EnvironmentalStory_20261113/before");Directory.CreateDirectory(backup);foreach(string file in new[]{"Materials/AE_M_Floor.mat","Materials/AE_M_Floor.mat.meta"})File.Copy(E+file,backup+"/"+Path.GetFileName(file),false);
 var group=new GameObject("EnvironmentalStory");group.transform.SetParent(root,false);
 // 1. Connect the actual machines and mark their use of the floor.
 var models=JArray.Parse(File.ReadAllText(Root+"/SourceAssets/F1_EnvironmentalStory/models.json"));foreach(var q in models.Where(q=>(string)q["kind"]!="roofFall"))Attach(Import(q),group.transform);
 mats["AE_M_Floor"].SetFloat("_AE_Mode",7);EditorUtility.SetDirty(mats["AE_M_Floor"]);
 // 2. Weather by ground contact and actual sill positions, retaining the old material GUID.
 File.Copy(Root+"/SourceAssets/F1_EnvironmentalStory/AEWeathering.hlsl",E+"AEWeathering.hlsl",true);AssetDatabase.ImportAsset(E+"AEWeathering.hlsl",ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);
 // 3. Relate debris to roof holes, and leaves to connected root systems.
 foreach(var q in models.Where(q=>(string)q["kind"]=="roofFall"))Attach(Import(q),group.transform);
 Attach(Import(JObject.Parse(File.ReadAllText(Root+"/SourceAssets/F1_EnvironmentalStory/litter.json"))),group.transform);
 var iq=JObject.Parse(File.ReadAllText(Root+"/SourceAssets/F1_EnvironmentalStory/ivy.json"));var proto=Import(iq);var source=proto.GetComponentsInChildren<MeshFilter>().ToDictionary(f=>f.name);var ivy=GameObject.Find("AE_WallIvy");foreach(var f in ivy.GetComponentsInChildren<MeshFilter>(true)){var src=source[f.name];f.sharedMesh=src.sharedMesh;f.GetComponent<Renderer>().sharedMaterials=src.GetComponent<Renderer>().sharedMaterials;if(PrefabUtility.IsPartOfPrefabInstance(f)){PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f.GetComponent<Renderer>());}}ivy.GetComponent<LODGroup>()?.RecalculateBounds();
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText(Out+"apply.json",JsonConvert.SerializeObject(instances,Formatting.Indented));return new{addedModels=instances.Count,ivyGUID=AssetDatabase.AssetPathToGUID(E+"AE_WallIvy.fbx"),saved=true};}
 public static object FloorBinding(){Check();var r=GameObject.Find("AE_InteriorFloor").GetComponent<Renderer>();var m=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/AE_M_Floor.mat");r.sharedMaterial=m;if(PrefabUtility.IsPartOfPrefabInstance(r))PrefabUtility.RecordPrefabInstancePropertyModifications(r);EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return new{floor=r.name,material=m.name,mode=m.GetFloat("_AE_Mode"),saved=true};}
 public static object RefineGrowth(){Check();PrepareMaterials();foreach(string file in new[]{"ivy","litter"}){var q=JObject.Parse(File.ReadAllText(Root+"/SourceAssets/F1_EnvironmentalStory/"+file+".json"));var proto=Import(q);var go=GameObject.Find(proto.name);var source=proto.GetComponentsInChildren<MeshFilter>().ToDictionary(f=>f.name);foreach(var f in go.GetComponentsInChildren<MeshFilter>(true)){var src=source[f.name];f.sharedMesh=src.sharedMesh;f.GetComponent<Renderer>().sharedMaterials=src.GetComponent<Renderer>().sharedMaterials;PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f.GetComponent<Renderer>());}go.GetComponent<LODGroup>()?.RecalculateBounds();}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return new{groundConformed=true,saved=true};}
 public static object Refine(){Check();File.Copy(Root+"/SourceAssets/F1_EnvironmentalStory/AEWeathering.hlsl",E+"AEWeathering.hlsl",true);AssetDatabase.ImportAsset(E+"AEWeathering.hlsl",ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);AssetDatabase.SaveAssets();return new{shaderUpdated=true};}
}
